class Solution {
    public int kInversePairs(int n,int k){
        long mod=1000000007L;
        long[] previous=new long[k+1];
        previous[0]=1;
        for(int length=1;length<=n;length++){
            long[] current=new long[k+1];
            long window=0;
            for(int inversions=0;inversions<=k;inversions++){
                window=(window+previous[inversions])%mod;
                if(inversions>=length)window=(window-previous[inversions-length]+mod)%mod;
                current[inversions]=window;
            }
            previous=current;
        }
        return(int)previous[k];
    }
}

